    // Check if the file exists before attempting to read.
    if (!fs.existsSync(absoluteYamlFilePath)) {
      return `Error: File not found at ${absoluteYamlFilePath}`;
    }

    // Read the YAML file content.
    const yamlContent = fs.readFileSync(absoluteYamlFilePath, 'utf8');

    // Handle empty file content
    if (yamlContent.trim() === '') {
      return 'Error: YAML file is empty.';
    }

    // Load the YAML content into a JavaScript object.
    const jsonObject = yaml.load(yamlContent);

    // Convert the JavaScript object to a JSON string.
    return JSON.stringify(jsonObject);
  } catch (error) {
    // Return an error message if any exception occurs during file reading or YAML parsing.
